        public boolean rdSaveImageToGallery(String path, String displayName) {
            try {
                java.io.File src = new java.io.File(path);
                if (!src.exists()) return false;
                android.content.ContentValues values = new android.content.ContentValues();
                values.put(android.provider.MediaStore.Images.Media.DISPLAY_NAME, displayName);
                values.put(android.provider.MediaStore.Images.Media.MIME_TYPE, "image/png");
                if (android.os.Build.VERSION.SDK_INT >= 29) {
                    values.put(android.provider.MediaStore.Images.Media.RELATIVE_PATH, "Pictures/RandomDraw");
                    values.put(android.provider.MediaStore.Images.Media.IS_PENDING, 1);
                }
                android.content.ContentResolver resolver = getContentResolver();
                android.net.Uri uri = resolver.insert(android.provider.MediaStore.Images.Media.EXTERNAL_CONTENT_URI, values);
                if (uri == null) return false;
                try (java.io.OutputStream out = resolver.openOutputStream(uri);
                     java.io.InputStream in = new java.io.FileInputStream(src)) {
                    byte[] buf = new byte[8192];
                    int n;
                    while ((n = in.read(buf)) > 0) out.write(buf, 0, n);
                }
                if (android.os.Build.VERSION.SDK_INT >= 29) {
                    values.clear();
                    values.put(android.provider.MediaStore.Images.Media.IS_PENDING, 0);
                    resolver.update(uri, values, null, null);
                }
                return true;
            } catch (Exception e) {
                android.util.Log.e("RDShare", "rdSaveImageToGallery failed", e);
                return false;
            }
        }

		public boolean rdShareImage(String path, String text) {
			try {
			java.io.File file = new java.io.File(path);
			android.net.Uri uri = androidx.core.content.FileProvider.getUriForFile(
			this, getPackageName() + ".fileprovider", file);

			android.content.Intent intent = new android.content.Intent(android.content.Intent.ACTION_SEND);
			intent.setType("image/*");
			intent.putExtra(android.content.Intent.EXTRA_STREAM, uri);
			if (text != null && !text.isEmpty()) {
			intent.putExtra(android.content.Intent.EXTRA_TEXT, text);
			}
			intent.addFlags(android.content.Intent.FLAG_GRANT_READ_URI_PERMISSION);

			android.content.Intent chooser = android.content.Intent.createChooser(intent, "Partager");
			chooser.setClipData(android.content.ClipData.newRawUri("", uri));
			chooser.addFlags(android.content.Intent.FLAG_GRANT_READ_URI_PERMISSION);
			startActivity(chooser);
			return true;
			} catch (Throwable t) {
			android.util.Log.e("RDShare", "rdShareImage a échoué", t);
			return false;
			}
			}

			public boolean rdShareText(String text) {
			try {
			android.content.Intent intent = new android.content.Intent(android.content.Intent.ACTION_SEND);
			intent.setType("text/plain");
			intent.putExtra(android.content.Intent.EXTRA_TEXT, text);
			startActivity(android.content.Intent.createChooser(intent, "Partager"));
			return true;
			} catch (Throwable t) {
			android.util.Log.e("RDShare", "rdShareText a échoué", t);
			return false;
			}
			}
